

--Q1. What is the total revenue generated by male vs. female customers?
SELECT
	gender,
	SUM(purchase_amount) as revenue
FROM	
	customer_shopping_behavior
group by	
	gender

--Q2. Which customers used a discount but still spent more than the average purchase amount? 

select
	customer_id,
	purchase_amount
from
	customer_shopping_behavior
where	
	discount_applied='Yes' and purchase_amount>(select AVG(purchase_amount) from customer_shopping_behavior)


-- Q3. Which are the top 5 products with the highest average review rating?
select 
	top 5
	item_purchased,
	round(AVG(review_rating),2) as avg_rating
from 
	customer_shopping_behavior
group by
	item_purchased
order by
	avg_rating desc


--Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
select
	shipping_type,
	AVG(purchase_Amount) as average_purchase_amount
from
	customer_shopping_behavior
group by	
	shipping_type


--Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.

select
	subscription_status,
	COUNT(*) as total_custoemrs,
	AVG(purchase_amount) as average_spend,
	SUM(purchase_amount) as total_revenue
from
	customer_shopping_behavior
group  by
	subscription_status


--Q6. Which 5 products have the highest percentage of purchases with discounts applied?

select
	top 5
	item_purchased,
	round(sum(case when discount_applied='Yes' then 1 else 0 end)*100.0/nullif(COUNT(*),0),2) as discount_rate
from
	customer_shopping_behavior
group by	
	item_purchased
order by
	discount_rate desc;

--Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment.

with customer_type as (
SELECT customer_id, previous_purchases,
CASE 
    WHEN previous_purchases = 1 THEN 'New'
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal'
    END AS customer_segment
FROM customer_shopping_behavior)

select customer_segment,count(*) AS "Number of Customers" 
from customer_type 
group by customer_segment;

--Q8. What are the top 3 most purchased products within each category? 

with items_count as (
select
	item_purchased,
	category,
	SUM(purchase_amount) as total_revenue,
	ROW_NUMBER()over(partition by category order by SUM(purchase_amount) desc ) as rn
from	
	customer_shopping_behavior
group by
	item_purchased,
	category
)
select
	item_purchased,
	category,
	rn as category_rank
from	
	items_count
where
	rn<=3;

--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

select
	subscription_status,
	COUNT(customer_id) as subs_count
from	
	customer_shopping_behavior
where
	previous_purchases<5
group by
	subscription_status

--Q10. What is the revenue contribution of each age group? 

select
	age_group,
	SUM(purchase_amount) as age_group_revenue
from
	customer_shopping_behavior
group by
	age_group
order by
	age_group_revenue desc